const results = await Promise.all([
  tools.exec_command({cmd:"/home/axel/.archon-env/bin/horizon inbox list --json 2>/dev/null | jq '{count:(.items|length),advisory_unread:.attention.advisory_unread_count,required:(.attention.required_protections|map(.id)),unread_conversations:(.attention.unread_conversations|map(.id)),warnings}'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"/home/axel/.archon-env/bin/horizon ps --json 2>/dev/null",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"ps -eo pid,ppid,stat,etime,%cpu,rss,args | rg -i '(^|/)(lake env lean|lake build|lean [^-]|lean$|timeout .*lean)( |$)' || true",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:8000})
]); results.forEach(r=>text(r.output));

