-{"name": "AlgebraicGeometry.point_ext_of_apply_closedPoint_eq", "kind": "theorem", "signature": "theorem point_ext_of_apply_closedPoint_eq [IsAlgClosed K] {T : Over (Spec (CommRingCat.of K))} [LocallyOfFiniteType T.hom] {p q : \ud835\udfd9_ (Over (Spec (CommRingCat.of K))) \u27f6 T} (h : p.left (IsLocalRing.closedPoint K) = q.left (IsLocalRing.closedPoint K)) : p = q", "doc": "Two `K`-points (in the `Over`-category sense) of a scheme locally of finite type over an algebraically closed field `K` are equal as soon as their underlying points agree.", "library": "Algebraic-Jacobian-Challenge-Rebuild", "file": "MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/AbelianVariety/Rigidity.lean", "line": 151}
